-- Additive SF research-only pilot. Legacy tables are not changed.
create table if not exists sf_pilot_searches (id text primary key,public_id text not null unique,brief_id text not null unique,name text not null,email text not null,revision integer not null default 1,extension_json text not null,requirement_revision_id text not null,status text not null default 'queued',generation integer not null default 1,created_at integer not null,updated_at integer not null);
create table if not exists sf_pilot_access (id text primary key,search_id text,token_hash text not null unique,role text not null check(role in ('claim','tenant','owner','staff')),generation integer not null,expires_at integer not null,used_at integer,revoked_at integer,created_at integer not null);
create index if not exists sf_pilot_access_search on sf_pilot_access(search_id,role);
create table if not exists sf_pilot_research (id text primary key,search_id text not null,revision integer not null,request_key text not null,note text not null,status text not null default 'queued',created_at integer not null,unique(search_id,revision,request_key));
create table if not exists sf_pilot_shortlists (id text primary key,search_id text not null,version integer not null,revision integer not null,requirement_revision_id text not null,status text not null check(status in ('draft','published','superseded')),items_json text not null,reviewer text,reviewed_at integer,created_at integer not null,unique(search_id,version));
create unique index if not exists sf_pilot_one_published on sf_pilot_shortlists(search_id) where status='published';
create table if not exists sf_pilot_feedback (id text primary key,search_id text not null,version integer not null,item_id text not null,action text not null,note text not null,request_key text not null,created_at integer not null,unique(search_id,request_key));
create table if not exists sf_pilot_inquiries (id text primary key,search_id text not null,revision integer not null,version integer not null,item_id text not null,purpose text not null,status text not null,payload_json text not null,context_hash text not null,consent_json text,receipt text,created_at integer not null,updated_at integer not null);
create unique index if not exists sf_pilot_inquiry_intent on sf_pilot_inquiries(search_id,revision,version,item_id,purpose) where status not in ('withdrawn','held');
create table if not exists sf_pilot_delivery (id text primary key,search_id text not null,kind text not null,version integer not null,grant_id text not null,recipient text not null,status text not null default 'pending',operation_key text not null unique,provider_id text,error text,attempts integer not null default 0,created_at integer not null,updated_at integer not null);
create table if not exists sf_pilot_rate_limits (bucket_hash text primary key,window_start integer not null,attempts integer not null);
